solution.solution.cpp:
#include <cstdint>
#include <string>
#include <vector>

struct Message { std::uint8_t type; std::uint32_t sequence; std::vector<std::uint8_t> payload; };

class Decoder
{
public:
    void feed(const std::vector<std::uint8_t>& bytes) { buffer.insert(buffer.end(), bytes.begin(), bytes.end()); }

    std::vector<Message> take()
    {
        std::vector<Message> out;
        std::size_t at{ 0 };
        while (buffer.size() - at >= 2)
        {
            const std::size_t length{ static_cast<std::size_t>((buffer[at] << 8) | buffer[at + 1]) };
            if (buffer.size() - at - 2 < length) break;
            if (length >= 5)
            {
                const std::size_t body{ at + 2 };
                Message m{ buffer[body], 0, {} };
                for (int k{ 0 }; k < 4; ++k) m.sequence = (m.sequence << 8) | buffer[body + 1 + k];
                m.payload.assign(buffer.begin() + static_cast<std::ptrdiff_t>(body + 5), buffer.begin() + static_cast<std::ptrdiff_t>(body + length));
                out.push_back(std::move(m));
            }
            at += 2 + length;
        }
        buffer.erase(buffer.begin(), buffer.begin() + static_cast<std::ptrdiff_t>(at));
        return out;
    }

    std::size_t pending() const { return buffer.size(); }

private:
    std::vector<std::uint8_t> buffer;
};

std::string describe(const Message& m)
{
    const std::string head{ "#" + std::to_string(m.sequence) + " " };
    const auto& p{ m.payload };
    const auto unknown = [&] { return head + "TYPE " + std::to_string(m.type) + " (" + std::to_string(p.size()) + " bytes)"; };
    switch (m.type)
    {
    case 1:
        if (p.empty() || p.size() != 1u + p[0]) return unknown();
        return head + "HELLO " + std::string(p.begin() + 1, p.end());
    case 2:
    {
        if (p.size() != 4) return unknown();
        const auto dx{ static_cast<std::int16_t>((p[0] << 8) | p[1]) }, dy{ static_cast<std::int16_t>((p[2] << 8) | p[3]) };
        return head + "MOVE dx=" + std::to_string(dx) + " dy=" + std::to_string(dy);
    }
    case 3:
    {
        if (p.size() < 2 || p.size() != 2u + ((p[0] << 8) | p[1])) return unknown();
        return head + "CHAT " + std::string(p.begin() + 2, p.end());
    }
    case 4:
        if (!p.empty()) return unknown();
        return head + "BYE";
    default:
        return unknown();
    }
}

std::vector<std::uint32_t> missing(const std::vector<Message>& messages)
{
    std::vector<std::uint32_t> gaps;
    for (std::size_t i{ 1 }; i < messages.size(); ++i)
        for (std::uint32_t s{ messages[i - 1].sequence + 1 }; s < messages[i].sequence; ++s) gaps.push_back(s);
    return gaps;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
static Bytes frame(std::uint8_t type, std::uint32_t seq, Bytes payload)
{
    const std::size_t length{ 5 + payload.size() };
    Bytes b{ static_cast<std::uint8_t>(length >> 8), static_cast<std::uint8_t>(length), type,
             static_cast<std::uint8_t>(seq >> 24), static_cast<std::uint8_t>(seq >> 16), static_cast<std::uint8_t>(seq >> 8), static_cast<std::uint8_t>(seq) };
    b.insert(b.end(), payload.begin(), payload.end());
    return b;
}
static Bytes session()
{
    Bytes s;
    for (const Bytes& f : { frame(1, 7, { 3, 'A', 'd', 'a' }), frame(2, 8, { 0x00, 0x03, 0xFF, 0xFF }), frame(3, 11, { 0x00, 0x02, 'g', 'g' }), frame(4, 12, {}) })
        s.insert(s.end(), f.begin(), f.end());
    return s;
}

TEST("whole messages") {
    Decoder d;
    d.feed(session());
    const auto m{ d.take() };
    CHECK_EQ(m.size(), 4u);
    if (m.size() != 4) return;
    CHECK_EQ(describe(m[0]), std::string("#7 HELLO Ada"));
    CHECK_EQ(describe(m[1]), std::string("#8 MOVE dx=3 dy=-1"));
    CHECK_EQ(describe(m[2]), std::string("#11 CHAT gg"));
    CHECK_EQ(describe(m[3]), std::string("#12 BYE"));
    CHECK_EQ(d.pending(), 0u);
    CHECK_EQ(missing(m), (std::vector<std::uint32_t>{ 9, 10 }));
}
TEST("split and joined reads") {
    const Bytes s{ session() };
    Decoder d;
    std::vector<Message> all;
    for (std::size_t at{ 0 }; at < s.size(); at += 3)
    {
        d.feed(Bytes(s.begin() + static_cast<std::ptrdiff_t>(at), s.begin() + static_cast<std::ptrdiff_t>(std::min(at + 3, s.size()))));
        for (Message& m : d.take()) all.push_back(m);
    }
    CHECK_EQ(all.size(), 4u);
    CHECK_EQ(d.pending(), 0u);
    Decoder half;
    half.feed(Bytes(s.begin(), s.begin() + 12));
    CHECK_EQ(half.take().size(), 1u);
    CHECK_EQ(half.pending(), 1u);
}
TEST("odd messages") {
    CHECK_EQ(describe(Message{ 9, 3, { 1, 2 } }), std::string("#3 TYPE 9 (2 bytes)"));
    CHECK_EQ(describe(Message{ 2, 4, { 1, 2 } }), std::string("#4 TYPE 2 (2 bytes)"));
    CHECK_EQ(describe(Message{ 1, 5, { 5, 'A' } }), std::string("#5 TYPE 1 (2 bytes)"));
    Decoder d;
    d.feed({ 0x00, 0x02, 0xAA, 0xBB });
    Bytes after{ frame(4, 1, {}) };
    d.feed(after);
    const auto m{ d.take() };
    CHECK_EQ(m.size(), 1u);
    if (!m.empty()) CHECK_EQ(describe(m[0]), std::string("#1 BYE"));
    CHECK(missing({}).empty());
}

